//! Revision-240 instruction numbers, independently owned by this adapter.
use crate::script::Opcode;
pub(super) fn opcode(value: u16) -> Opcode {
    OPCODES
        .binary_search_by_key(&value, |(number, _)| *number)
        .map_or(Opcode::Unsupported(value), |index| OPCODES[index].1)
}
